<script setup lang="ts">
import {computed,defineComponent,h,onMounted,ref} from 'vue';
const AdNativeInput=defineComponent({inheritAttrs:false,props:{modelValue:{type:String,default:''}},emits:['update:modelValue'],setup(p,{attrs,emit}){return()=>h('input',{...attrs,value:p.modelValue,onInput:(e:Event)=>emit('update:modelValue',(e.target as HTMLInputElement).value)})}});
import type {Platform} from '@/domain/types';
import {api} from '@/services/api';
import {advertisingApi,type AdConfig,type AdReport,type AdCreative,type AdChannel,type AdDiagnosis} from '@/services/advertising';
const props=defineProps<{platform:Platform}>();
const names:Record<Platform,string>={mobile:'手机客户端',tablet:'平板客户端',tv:'电视客户端',web:'电脑客户端'};
const systems=computed(()=>props.platform==='web'?['windows','web']:props.platform==='tv'?['android']:['android','ios']);
const osNames:Record<string,string>={android:'Android',ios:'iOS / iPadOS',windows:'Windows',web:'Web'};
const tabs=[['overview','广告概览'],['slots','广告位管理'],['creatives','自定义广告'],['channels','SDK 与渠道'],['rules','投放规则'],['rewards','激励与奖励'],['diagnostics','数据与诊断']];
const tab=ref('overview'),report=ref<AdReport|null>(null),config=ref<AdConfig|null>(null),busy=ref(''),error=ref(''),message=ref('');
const copy=<T,>(v:T):T=>JSON.parse(JSON.stringify(v));
const dirty=computed(()=>!!report.value&&JSON.stringify(config.value)!==JSON.stringify(report.value.draft));
const unpublished=computed(()=>!!report.value&&JSON.stringify(report.value.draft)!==JSON.stringify(report.value.published));
const label=(id:string)=>report.value?.slotNames[id]||id;
const activeCount=computed(()=>config.value?.creatives.filter(x=>x.status==='active').length||0);
const enabledSlots=computed(()=>config.value?.slots.filter(x=>x.enabled).length||0);
const statusName=(s:string)=>({draft:'草稿',active:'投放中',paused:'已暂停'}[s]||s);
const sourceName=(s:string)=>s==='sdk'?'SDK 渠道':s==='custom'?'自定义广告':s;
const eventNames:Record<string,string>={decision:'请求填充',impression:'曝光上报',click:'点击上报',complete:'完成上报',error:'加载错误',no_fill:'渠道无填充',fallback:'自定义兜底',reward_verified:'验签发奖'};
const fmt=(t:string)=>t?new Date(t).toLocaleString('zh-CN',{hour12:false}):'尚未发布';
async function action(name:string,run:()=>Promise<void>){if(busy.value)return;busy.value=name;error.value='';message.value='';try{await run()}catch(e){error.value=(e as Error).message}finally{busy.value=''}}
function accept(v:AdReport){report.value=v;config.value=copy(v.draft)}
async function load(){await action('读取',async()=>{accept(await advertisingApi.get(props.platform))})}
async function save(){await action('保存',async()=>{if(!config.value||!report.value)return;accept(await advertisingApi.save(props.platform,report.value.version,config.value));message.value='广告草稿已保存，发布后客户端才能获取。'})}
async function publish(){await action('发布',async()=>{if(!config.value||!report.value)return;if(dirty.value)accept(await advertisingApi.save(props.platform,report.value.version,config.value));accept(await advertisingApi.publish(props.platform,report.value.version));message.value='当前客户端广告配置已发布。'})}
const creative=ref<AdCreative|null>(null),channel=ref<AdChannel|null>(null),formError=ref(''),startInput=ref(''),endInput=ref('');
const localDate=(t:string)=>{if(!t)return '';const d=new Date(t);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
function editCreative(x?:AdCreative){formError.value='';creative.value=x?copy(x):{id:crypto.randomUUID(),name:'',advertiser:'',orderNo:'',kind:'house',slot:'splash',status:'draft',media:'image',asset:'',text:'',destination:'none',url:'',os:[...systems.value],priority:100,start:'',end:'',duration:5,skipAfter:3};startInput.value=localDate(creative.value.start);endInput.value=localDate(creative.value.end)}
function applyCreative(){const x=creative.value;if(!x||!config.value)return;formError.value='';if(!x.name.trim()||!x.os.length||(!x.asset&&x.media!=='text')||(!x.text.trim()&&x.media==='text')){formError.value='请填写名称、目标系统和对应的广告素材或文案。';return}if(x.destination==='url'&&!x.url.toLowerCase().startsWith('https://')){formError.value='请输入 HTTPS 落地页地址。';return}if([startInput.value,endInput.value].some(t=>t&&!Number.isFinite(new Date(t).getTime()))){formError.value='请选择有效的投放时间。';return}x.start=startInput.value?new Date(startInput.value).toISOString():'';x.end=endInput.value?new Date(endInput.value).toISOString():'';if(x.start&&x.end&&x.end<=x.start){formError.value='结束时间需要晚于开始时间。';return}if(x.destination!=='url')x.url='';const i=config.value.creatives.findIndex(v=>v.id===x.id);if(i<0)config.value.creatives.push(copy(x));else config.value.creatives[i]=copy(x);creative.value=null}
async function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f||!creative.value)return;formError.value='';if(f.size>12*1024*1024){formError.value='素材大小不能超过12 MiB。';return}busy.value='上传';try{const data=await new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(Error('文件读取失败'));r.readAsDataURL(f)});const out=await api.asset(f.name,data);if(creative.value)creative.value.asset=out.url}catch(e){formError.value=(e as Error).message}finally{busy.value=''}}
function editChannel(x?:AdChannel){formError.value='';channel.value=x?copy(x):{id:crypto.randomUUID(),name:'',provider:'admob',os:systems.value[0],enabled:false,appId:'',units:{}}}
function applyChannel(){const x=channel.value;if(!x||!config.value)return;if(!x.name.trim()){formError.value='请填写渠道名称。';return}for(const k of Object.keys(x.units))if(!x.units[k].trim())delete x.units[k];if(x.provider!=='admob')x.enabled=false;const i=config.value.channels.findIndex(v=>v.id===x.id);if(i<0)config.value.channels.push(copy(x));else config.value.channels[i]=copy(x);channel.value=null}
const diagnostic=ref<AdDiagnosis|null>(null),testOS=ref(systems.value[0]),testSlot=ref('splash');
async function diagnose(){await action('检测',async()=>{diagnostic.value=await advertisingApi.diagnose(props.platform,testOS.value,testSlot.value)})}
async function copyCallback(){await action('复制',async()=>{await navigator.clipboard.writeText(report.value?.callbackUrl||'');message.value='回调地址已复制。'})}
const search=ref('');const creatives=computed(()=>config.value?.creatives.filter(x=>(x.name+' '+x.advertiser+' '+x.orderNo).toLowerCase().includes(search.value.toLowerCase()))||[]);
const ctr=computed(()=>{const m=report.value?.totals;return m&&m.impressions?(100*m.clicks/m.impressions).toFixed(2)+'%':'—'});
onMounted(load);
</script>

<template>
<section class="ad-center" :aria-busy="!!busy">
 <header class="ad-head"><div><div class="ad-eyebrow">ADVERTISING / {{names[platform]}}</div><h1>广告中心 <span>独立投放 · 精准控制</span></h1><p>统一管理广告内容、SDK 渠道、投放规则与实际回传记录。</p></div><div class="ad-actions"><span class="ad-save-state">{{dirty?'有未保存修改':unpublished?'草稿待发布':'草稿已同步'}}</span><button :disabled="!!busy||dirty" @click="load">刷新数据</button><button :disabled="!!busy||!dirty" @click="save">保存草稿</button><button class="ad-primary" :disabled="!!busy||(!dirty&&!unpublished&&!!report?.publishedVersion)" @click="publish">{{busy==='发布'?'正在发布…':'发布配置'}}</button></div></header>
 <div v-if="error" class="ad-alert ad-error" role="alert">{{error}}</div><div v-if="message" class="ad-alert ad-success" role="status">{{message}}</div>
 <div v-if="!report||!config" class="ad-empty"><strong>{{busy?'正在读取广告配置…':'广告配置读取失败'}}</strong><p>数据来自本机服务端广告接口。</p><button v-if="!busy" @click="load">重新读取</button></div>
 <template v-else>
 <nav class="ad-tabs" aria-label="广告中心功能"><button v-for="t in tabs" :key="t[0]" :class="{selected:tab===t[0]}" @click="tab=t[0]">{{t[1]}}</button></nav>
 <div class="ad-meta"><span class="ad-dot"></span><span>{{names[platform]}}广告配置</span><span class="ad-muted">{{report.publishedVersion?'已发布 v'+report.publishedVersion:'尚未发布'}} · {{report.publishedAt?fmt(report.publishedAt):'保存草稿后发布生效'}}</span><span class="ad-meta-end">数据更新时间 {{fmt(report.checkedAt)}}</span></div>
 <template v-if="tab==='overview'">
 <div class="ad-kpis"><article><small>今日广告请求</small><strong>{{report.today.requests.toLocaleString()}}</strong><span>服务端实际请求</span></article><article><small>今日成功填充</small><strong>{{report.today.fills.toLocaleString()}}</strong><span>已分配广告任务</span></article><article><small>今日曝光</small><strong>{{report.today.impressions.toLocaleString()}}</strong><span>客户端上报去重</span></article><article><small>今日点击</small><strong>{{report.today.clicks.toLocaleString()}}</strong><span>客户端上报去重</span></article></div>
 <div class="ad-columns"><article class="ad-panel"><div class="ad-section-title"><h2>投放准备情况</h2><span class="ad-tag">当前草稿</span></div><div class="ad-readiness"><div><b>{{enabledSlots}} / 8</b><span>开启的广告位</span></div><div><b>{{activeCount}}</b><span>已启用素材</span></div><div><b>{{config.channels.filter(x=>x.enabled).length}}</b><span>已启用渠道</span></div></div><div class="ad-row-link" @click="tab='slots'"><span>01　设置广告位与来源</span><span>前往管理 →</span></div><div class="ad-row-link" @click="tab='creatives'"><span>02　上传素材或登记渠道</span><span>配置内容 →</span></div><div class="ad-row-link" @click="tab='diagnostics'"><span>03　发布并检查投放条件</span><span>检查配置 →</span></div></article><article class="ad-panel"><div class="ad-section-title"><h2>近 30 天实际表现</h2><span class="ad-muted">UTC 日界线</span></div><dl class="ad-summary"><div><dt>请求 / 填充</dt><dd>{{report.totals.requests}} / {{report.totals.fills}}</dd></div><div><dt>曝光 / 点击率</dt><dd>{{report.totals.impressions}} / {{ctr}}</dd></div><div><dt>加载失败与无填充</dt><dd>{{report.totals.errors}}</dd></div><div><dt>验签奖励 / 运营积分</dt><dd>{{report.totals.rewards}} / {{report.totals.points}}</dd></div></dl><p class="ad-footnote">曝光、点击由客户端回传；奖励仅在官方服务端验签通过后计入。尚无请求时显示真实的 0。</p></article></div>
 <article class="ad-panel"><div class="ad-section-title"><h2>最近投放动态</h2><button @click="tab='diagnostics'">查看记录 →</button></div><div v-if="!report.events.length" class="ad-empty"><span class="ad-empty-icon">▥</span><strong>还没有投放记录</strong><p>发布广告后，真实客户端请求和回传将在这里出现。</p></div><div v-for="e in report.events.slice(0,5)" :key="e.at+e.type" class="ad-log"><span class="ad-tag">{{eventNames[e.type]||e.type}}</span><span>{{label(e.slot)}}</span><span class="ad-muted">{{sourceName(e.source)}}</span><time>{{fmt(e.at)}}</time></div></article>
 </template>
 <article v-else-if="tab==='slots'" class="ad-panel"><div class="ad-section-title"><div><h2>广告位管理</h2><p>广告位由主题和客户端提供，开启后按当前端发布配置请求广告。</p></div><span class="ad-tag">8 个固定广告位</span></div><div class="ad-table-wrap"><table><thead><tr><th>广告位</th><th>状态</th><th>广告来源</th><th>素材数量</th><th>会员免广告</th><th>频控</th></tr></thead><tbody><tr v-for="s in config.slots" :key="s.id"><td><strong>{{label(s.id)}}</strong><small>{{s.id}}</small></td><td><button class="ad-toggle" role="switch" :aria-checked="s.enabled" @click="s.enabled=!s.enabled"><span :class="{on:s.enabled}"></span>{{s.enabled?'已开启':'已关闭'}}</button></td><td><select v-model="s.order"><option value="custom-first">自定义优先 · SDK 兜底</option><option value="sdk-first">SDK 优先 · 自定义兜底</option><option value="custom-only">仅自定义广告</option><option value="sdk-only">仅 SDK 渠道</option></select></td><td>{{config.creatives.filter(x=>x.slot===s.id).length}}</td><td><button class="ad-choice" :aria-pressed="s.excludeVip" @click="s.excludeVip=!s.excludeVip">{{s.excludeVip?'✓ 已开启':'未开启'}}</button></td><td><button @click="tab='rules'">{{s.dailyCap}} 次/日 · {{s.cooldownSeconds}} 秒 →</button></td></tr></tbody></table></div></article>
 <article v-else-if="tab==='creatives'" class="ad-panel"><div class="ad-section-title"><div><h2>自定义广告</h2><p>管理自营推广与直客商业广告，素材由本机实际保存并提供。</p></div><button class="ad-primary" @click="editCreative()">＋ 新建广告</button></div><div class="ad-toolbar"><input v-model="search" placeholder="搜索广告名称、广告主或订单编号"/><span class="ad-muted">共 {{creatives.length}} 条 · 每端最多 100 条</span></div><div v-if="!creatives.length" class="ad-empty"><span class="ad-empty-icon">▧</span><strong>还没有自定义广告</strong><p>上传图片、视频或填写文字，再设置广告位与投放时间。</p><button @click="editCreative()">创建第一条广告</button></div><div v-else class="ad-table-wrap"><table><thead><tr><th>广告 / 广告主</th><th>类型</th><th>广告位 / 系统</th><th>投放时间</th><th>优先级</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="c in creatives" :key="c.id"><td><strong>{{c.name}}</strong><small>{{c.advertiser||'自营推广'}} {{c.orderNo}}</small></td><td>{{c.kind==='house'?'自营推广':'直客商业'}}</td><td>{{label(c.slot)}}<small>{{c.os.map(x=>osNames[x]).join(' / ')}}</small></td><td>{{c.start?fmt(c.start):'立即开始'}}<small>{{c.end?fmt(c.end):'长期投放'}}</small></td><td>{{c.priority}}</td><td><span class="ad-tag" :class="{'ad-green':c.status==='active'}">{{statusName(c.status)}}</span></td><td><button @click="editCreative(c)">编辑</button><button @click="c.status=c.status==='active'?'paused':'active'">{{c.status==='active'?'暂停':'启用'}}</button></td></tr></tbody></table></div></article>
 <article v-else-if="tab==='channels'" class="ad-panel"><div class="ad-section-title"><div><h2>SDK 与渠道</h2><p>配置各系统的应用 ID 和广告单元。客户端需编译对应 SDK 并完成真机验收。</p></div><button class="ad-primary" @click="editChannel()">＋ 添加渠道</button></div><div v-if="!config.channels.length" class="ad-empty"><span class="ad-empty-icon">⇄</span><strong>尚未配置广告渠道</strong><p>AdMob 已实现服务端奖励验签协议。其他渠道当前可登记，适配前无法启用。</p><button @click="editChannel()">配置渠道</button></div><div v-for="ch in config.channels" :key="ch.id" class="ad-channel"><div class="ad-channel-icon">{{ch.provider==='admob'?'G':'⇄'}}</div><div class="ad-channel-info"><h3>{{ch.name}} <span class="ad-tag">{{osNames[ch.os]}}</span></h3><p>{{ch.provider.toUpperCase()}} · {{Object.keys(ch.units).length}} 个广告单元 · {{ch.enabled?'配置已启用':'未启用'}}</p><span class="ad-amber">{{ch.provider==='admob'?'客户端 SDK 尚未验收':'服务商适配器未实现'}}</span></div><button @click="editChannel(ch)">编辑渠道</button></div></article>
 <article v-else-if="tab==='rules'" class="ad-panel"><div class="ad-section-title"><div><h2>投放规则</h2><p>按设备与广告位控制请求分配。每日次数采用 UTC 日界线；成功分配即占用一次，防止反复取广告。</p></div></div><div class="ad-table-wrap"><table><thead><tr><th>广告位</th><th>设备每日上限</th><th>冷却时间（秒）</th><th>每 N 次请求投放</th><th>会员免广告</th></tr></thead><tbody><tr v-for="s in config.slots" :key="s.id"><td><strong>{{label(s.id)}}</strong><small>{{s.enabled?'已开启':'已关闭'}}</small></td><td><input type="number" min="1" max="1000" v-model.number="s.dailyCap"/></td><td><input type="number" min="0" max="86400" v-model.number="s.cooldownSeconds"/></td><td><input type="number" min="1" max="1000" v-model.number="s.every"/></td><td><button class="ad-choice" :aria-pressed="s.excludeVip" @click="s.excludeVip=!s.excludeVip">{{s.excludeVip?'✓ 已开启':'未开启'}}</button></td></tr></tbody></table></div><p class="ad-footnote">会员身份由真实 CMS 登录会话核验。SDK 无填充时按来源顺序尝试自定义广告，兜底不重复占用次数。</p></article>
 <template v-else-if="tab==='rewards'"><div class="ad-columns"><article class="ad-panel"><div class="ad-section-title"><h2>激励奖励规则</h2><button class="ad-toggle" role="switch" :aria-checked="config.reward.enabled" @click="config.reward.enabled=!config.reward.enabled"><span :class="{on:config.reward.enabled}"></span>{{config.reward.enabled?'已开启':'已关闭'}}</button></div><div class="ad-form"><label>单次奖励（运营积分）<input type="number" min="1" max="10000" v-model.number="config.reward.points"/></label><label>每位用户每日最多领取<input type="number" min="1" max="100" v-model.number="config.reward.dailyCap"/></label><label>两次领取间隔（秒）<input type="number" min="30" max="86400" v-model.number="config.reward.cooldownSeconds"/></label></div><p class="ad-footnote">需要登录真实会员、开启激励广告位并配置 AdMob 激励单元。运营积分单独记账，当前不写入 CMS 积分。</p></article><article class="ad-panel"><div class="ad-section-title"><h2>服务端验签回调</h2><span class="ad-tag">AdMob SSV</span></div><p class="ad-muted">将此地址填入 AdMob 激励广告单元的服务端验证设置。</p><code class="ad-code">{{report.callbackUrl}}</code><button @click="copyCallback">复制回调地址</button><ol class="ad-steps"><li>客户端登录并请求激励广告任务。</li><li>SDK 携带任务 customData 与 userId 展示广告。</li><li>官方回调验签通过后，原子记账并防止重复发奖。</li></ol></article></div><article class="ad-panel"><div class="ad-section-title"><h2>已验证奖励账本</h2><span class="ad-muted">{{report.rewards.length}} 笔实际记录</span></div><div v-if="!report.rewards.length" class="ad-empty"><strong>暂无已验证奖励</strong><p>客户端播放完成上报不会直接发奖。</p></div><div v-else class="ad-table-wrap"><table><thead><tr><th>发放时间</th><th>交易号</th><th>用户标识</th><th>积分</th></tr></thead><tbody><tr v-for="rw in report.rewards.slice(0,100)" :key="rw.id"><td>{{fmt(rw.at)}}</td><td>{{rw.transaction}}</td><td>{{rw.user.slice(0,16)}}…</td><td>+{{rw.points}}</td></tr></tbody></table></div></article></template>
 <template v-else-if="tab==='diagnostics'"><article class="ad-panel"><div class="ad-section-title"><div><h2>已发布配置检查</h2><p>读取当前端已发布配置、检查素材文件并计算匹配结果；不产生曝光、点击或奖励。</p></div></div><div class="ad-toolbar"><select v-model="testOS"><option v-for="s in systems" :key="s" :value="s">{{osNames[s]}}</option></select><select v-model="testSlot"><option v-for="s in config.slots" :key="s.id" :value="s.id">{{label(s.id)}}</option></select><button class="ad-primary" :disabled="!!busy" @click="diagnose">{{busy==='检测'?'正在检查…':'检查投放配置'}}</button></div><div v-if="diagnostic" class="ad-diagnosis"><div v-for="c in diagnostic.checks" :key="c.name" class="ad-check"><span :class="c.ok?'ad-green':'ad-amber'">{{c.ok?'✓ 通过':'! 待处理'}}</span><span>{{c.name}}</span><span class="ad-muted">{{c.error}}</span></div><div class="ad-alert">{{diagnostic.reason}}<br/>{{diagnostic.message}}</div></div></article><article class="ad-panel"><div class="ad-section-title"><h2>实际事件记录</h2><span class="ad-muted">保留最近 500 条 · {{report.events.length}} 条</span></div><div v-if="!report.events.length" class="ad-empty"><strong>暂无客户端事件</strong><p>通过真实客户端调用后显示回传状态及错误码。</p></div><div v-else class="ad-table-wrap"><table><thead><tr><th>时间</th><th>事件</th><th>广告位</th><th>来源</th><th>任务标识</th><th>错误码</th></tr></thead><tbody><tr v-for="(e,i) in report.events" :key="i"><td>{{fmt(e.at)}}</td><td>{{eventNames[e.type]||e.type}}</td><td>{{label(e.slot)}}</td><td>{{sourceName(e.source)}}</td><td><code>{{e.decision}}</code></td><td>{{e.code||'—'}}</td></tr></tbody></table></div></article></template>
 </template>
 <div v-if="creative||channel" class="ad-overlay" @click.self="!busy&&(creative=null,channel=null)"><section class="ad-drawer" role="dialog" aria-modal="true" :aria-label="creative?'广告编辑':'渠道编辑'"><header><div><div class="ad-eyebrow">{{names[platform]}}</div><h2>{{creative?'编辑自定义广告':'配置 SDK 渠道'}}</h2></div><button :disabled="!!busy" aria-label="关闭" @click="creative=null;channel=null">✕</button></header><div class="ad-drawer-body"><div v-if="formError" class="ad-alert ad-error">{{formError}}</div>
 <div v-if="creative" class="ad-form"><label>广告名称<input v-model="creative.name" maxlength="120" placeholder="填写便于识别的名称"/></label><div class="ad-form-two"><label>业务类型<select v-model="creative.kind"><option value="house">自营推广</option><option value="commercial">直客商业广告</option></select></label><label>投放状态<select v-model="creative.status"><option value="draft">草稿</option><option value="active">启用</option><option value="paused">暂停</option></select></label><label>广告主<input v-model="creative.advertiser" maxlength="120"/></label><label>订单编号<input v-model="creative.orderNo" maxlength="120"/></label><label>广告位<select v-model="creative.slot"><option v-for="s in config?.slots.filter(x=>x.id!=='rewarded')" :key="s.id" :value="s.id">{{label(s.id)}}</option></select></label><label>优先级<input type="number" min="0" max="1000" v-model.number="creative.priority"/></label></div><label>目标系统<div class="ad-checkboxes"><button v-for="s in systems" :key="s" class="ad-choice" :aria-pressed="creative.os.includes(s)" @click="creative.os=creative.os.includes(s)?creative.os.filter(x=>x!==s):[...creative.os,s]">{{creative.os.includes(s)?'✓ ':''}}{{osNames[s]}}</button></div></label><label>素材类型<select v-model="creative.media" @change="creative.asset='' "><option value="image">图片</option><option value="video">MP4 视频</option><option value="text">文字</option></select></label><label v-if="creative.media!=='text'">上传素材 · 最大 12 MiB<AdNativeInput type="file" :accept="creative.media==='video'?'.mp4':'.png,.jpg,.jpeg,.webp'" :disabled="!!busy" @change="upload"/><span v-if="creative.asset" class="ad-green">✓ 素材已保存</span><img v-if="creative.asset&&creative.media==='image'" class="ad-asset" :src="creative.asset" alt="广告素材"/><video v-if="creative.asset&&creative.media==='video'" class="ad-asset" :src="creative.asset" controls/></label><label>广告文案<textarea v-model="creative.text" maxlength="2000" rows="3"/></label><div class="ad-form-two"><label>跳转目标<select v-model="creative.destination"><option value="none">不跳转</option><option value="url">HTTPS 链接</option><option value="home">首页</option><option value="search">搜索</option><option value="member">会员中心</option></select></label><label>展示时长（秒）<input type="number" min="1" max="120" v-model.number="creative.duration"/></label></div><label v-if="creative.destination==='url'">落地页地址<input v-model="creative.url" placeholder="https://" maxlength="2048"/></label><div class="ad-form-two"><label>开始时间 · 本地时区<AdNativeInput type="datetime-local" v-model="startInput"/></label><label>结束时间 · 本地时区<AdNativeInput type="datetime-local" v-model="endInput"/></label><label>可跳过时间（秒）<input type="number" min="0" :max="creative.duration" v-model.number="creative.skipAfter"/></label></div><p class="ad-footnote">时间留空表示不限制。启用且在投放时间内的素材才参与匹配，优先级较高的优先展示。</p></div>
 <div v-else-if="channel" class="ad-form"><label>渠道名称<input v-model="channel.name" maxlength="120"/></label><div class="ad-form-two"><label>服务商<select v-model="channel.provider" @change="channel.enabled=false"><option value="admob">Google AdMob</option><option value="pangle">穿山甲 · 待适配</option><option value="gromore">GroMore · 待适配</option><option value="tanx">Tanx · 待适配</option><option value="other">其他 · 待适配</option></select></label><label>目标系统<select v-model="channel.os"><option v-for="s in systems" :key="s" :value="s">{{osNames[s]}}</option></select></label></div><label>App ID<input v-model="channel.appId" placeholder="ca-app-pub-…~…" maxlength="120"/></label><button class="ad-choice" :aria-pressed="channel.enabled" :disabled="channel.provider!=='admob'||platform==='tv'||platform==='web'" @click="channel.enabled=!channel.enabled">{{channel.enabled?'✓ 已启用渠道':'启用此渠道配置'}}</button><div class="ad-alert">{{channel.provider==='admob'?'服务端支持 AdMob SSV；原生 SDK 需要在打包器对应客户端编译接入并真机验证。':'此渠道尚未实现服务商适配器，当前仅可保存配置，不能启用。'}}</div><h3>广告单元映射</h3><label v-for="s in config?.slots" :key="s.id">{{label(s.id)}}<input v-model="channel.units[s.id]" placeholder="未配置 · ca-app-pub-…/…" maxlength="120"/></label></div>
 </div><footer><span class="ad-muted">保存后回到页面发布生效</span><button :disabled="!!busy" @click="creative=null;channel=null">取消</button><button class="ad-primary" :disabled="!!busy" @click="creative?applyCreative():applyChannel()">{{busy==='上传'?'素材上传中…':'加入草稿'}}</button></footer></section></div>
</section>
</template>

